@font-face{font-family:ChmInter;font-style:normal;font-weight:100 900;font-display:swap;src:url('/fonts/Inter-Variable.woff') format('woff')}
@font-face{font-family:ChmSerif;font-style:normal;font-weight:200 900;font-display:swap;src:url('/fonts/SourceSerif4-Variable.woff') format('woff')}
html{scroll-behavior:smooth;scroll-padding-top:30px}body{margin:0}
.chm{--cream:#fff7ea;--paper:#fffcf6;--green:#23483f;--deep:#183d33;--coral:#ad503d;--oat:#f1e6d6;--sage:#e4eadc;--line:#ded6c6;--muted:#57685e;color:var(--green);background:var(--cream);font-family:ChmInter,Arial,sans-serif;font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased}
.chm *,.chm *::before,.chm *::after{box-sizing:border-box}.chm h1,.chm h2,.chm h3,.chm p,.chm figure{margin:0}.chm h1,.chm h2,.chm h3{font-family:ChmSerif,Georgia,serif;font-weight:500;letter-spacing:-.045em;line-height:1.08}.chm h2{font-size:clamp(34px,4vw,51px)}.chm h3{font-size:27px}.chm a{color:inherit;text-underline-offset:5px}.chm img{display:block;max-width:100%;height:auto}.chm a:focus-visible,.chm summary:focus-visible{outline:3px solid var(--coral);outline-offset:5px}.chm :target{scroll-margin-top:30px}.chm main:focus{outline:0}.chm-wrap{max-width:1320px;padding-inline:60px;margin-inline:auto}
.chm-skip{position:absolute;top:8px;left:8px;background:var(--green);color:white!important;padding:12px;z-index:100;transform:translateY(-150%)}.chm-skip:focus{transform:none}
.chm-header{display:flex;gap:32px;align-items:center;min-height:100px;position:relative}.chm-header::after{content:'';position:absolute;bottom:0;left:60px;right:60px;border-bottom:1px solid var(--line)}.chm-logo{text-decoration:none;display:grid;gap:3px;min-width:102px}.chm-logo span{font-size:8px;letter-spacing:.19em;font-weight:600;text-align:center}.chm-nav{display:flex;gap:30px;margin-left:auto;font-size:13px;font-weight:500}.chm-nav a{text-decoration:none;min-height:44px;display:flex;align-items:center}.chm-nav a[aria-current=page]{color:var(--coral)}.chm-nav a:hover,.chm-header-login:hover{text-decoration:underline}.chm-header-login{display:flex;align-items:center;justify-content:center;gap:20px;text-decoration:none;font-size:13px;border:1px solid #bfc8b9;min-height:44px;padding:8px 22px;border-radius:30px;margin-left:20px}.chm-menu{display:none}
.chm-hero{display:grid;grid-template-columns:1.03fr 1fr;gap:65px;align-items:center;padding-block:70px 74px}.chm-eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:11px;font-weight:700;color:var(--coral);margin-bottom:20px!important}.chm-hero-title{font-size:clamp(50px,5.05vw,74px);line-height:1.04!important;max-width:650px}.chm-hero-title em{font-weight:500;color:var(--coral)}.chm-lead{font-size:17px;line-height:1.75;max-width:520px;color:var(--muted);margin-top:25px!important}.chm-actions{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-top:29px}.chm-button{display:inline-flex;gap:18px;justify-content:center;align-items:center;min-height:52px;background:var(--green);border:1px solid var(--green);border-radius:40px;color:var(--cream)!important;text-decoration:none;font:600 13px/1.4 ChmInter,Arial,sans-serif;padding:15px 25px;transition:background .18s,transform .18s;cursor:pointer;text-align:center}.chm-button:hover{background:var(--deep);transform:translateY(-2px)}.chm-button-secondary{background:transparent;color:var(--green)!important;border-color:#bfc8b9}.chm-button-secondary:hover{background:var(--oat)}.chm-microcopy{color:var(--muted);font-size:11px;line-height:1.6;margin-top:15px!important}.chm-hero-visual{position:relative;min-width:0}.chm-hero-photo{width:100%;aspect-ratio:1.02;object-fit:cover;border-radius:160px 160px 14px 14px;object-position:48% center}.chm-balance-card{position:absolute;left:-30px;bottom:28px;background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:20px 25px;min-width:225px;box-shadow:0 14px 40px #183d3314}
.chm-benefit-strip{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding-block:28px;gap:32px}.chm-benefit-item{display:flex;gap:14px;align-items:center;font-size:13px}.chm-benefit-item strong{font-weight:600}.chm-benefit-item p{font-size:12px;color:var(--muted);margin-top:4px}.chm-benefit-item svg{width:25px;height:25px;flex-shrink:0;stroke-width:1.5}
.chm-section{padding-block:88px}.chm-section-heading{max-width:670px;margin-bottom:38px}.chm-section-heading .chm-eyebrow{margin-bottom:14px!important}.chm-section-heading>p:not(.chm-eyebrow){margin-top:18px;color:var(--muted);font-size:15px;max-width:590px}.chm-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:42px}.chm-step{border-top:1px solid #b6c3b2;padding-top:24px}.chm-step>span:first-child,.chm-step-number{font:500 14px ChmInter,Arial,sans-serif;color:var(--coral);display:block;margin-bottom:22px}.chm-step h3{font-size:28px;margin-bottom:14px}.chm-step p{font-size:14px;color:var(--muted);max-width:330px}.chm-split{display:grid;grid-template-columns:1fr 1fr;gap:90px;align-items:center}.chm-story{background:var(--sage)}.chm-story-visual{position:relative;min-width:0}.chm-story-visual>img{border-radius:12px;width:100%;aspect-ratio:1.12;object-fit:cover}.chm-story h2{margin-bottom:24px}.chm-story p:not(.chm-eyebrow){color:var(--muted);font-size:15px}.chm-story .chm-actions{margin-top:24px}
.chm-packages{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;align-items:stretch}.chm-package{position:relative;display:flex;flex-direction:column;align-items:flex-start;border:1px solid var(--line);border-radius:14px;background:var(--paper);padding:26px 23px;color:var(--green)}.chm-package h3{font-size:29px;margin-bottom:20px}.chm-package-featured{background:var(--green);color:var(--cream);border-color:var(--green)}.chm-package-featured .chm-button{background:var(--cream);color:var(--green)!important;border-color:var(--cream)}.chm-badge{display:inline-flex;align-items:center;border-radius:30px;padding:5px 10px;background:var(--sage);color:var(--green);font-size:10px;font-weight:600;letter-spacing:.02em;line-height:1.4}.chm-package>.chm-badge{margin-bottom:20px}.chm-package-featured .chm-badge{background:#e6b59b;color:#253d32}.chm-price{font-family:ChmSerif,Georgia,serif;font-size:43px;letter-spacing:-.04em;line-height:1.15}.chm-price small{font:400 11px ChmInter,Arial,sans-serif;letter-spacing:0}.chm-package-total{font-weight:600;font-size:14px;margin-top:22px!important}.chm-package p{font-size:12px;line-height:1.65}.chm-package .chm-button{width:100%;margin-top:24px;padding-inline:10px;font-size:11px}.chm-package .chm-microcopy{margin-top:8px!important}.chm-package-featured .chm-microcopy{color:#d5e1d2}.chm-package .chm-price{font-size:43px}.chm-package-featured a:hover{background:#f4e5ce}.chm-package>p:last-of-type{margin-bottom:auto}.chm-packages-note{font-size:12px;color:var(--muted);line-height:1.8;max-width:800px;margin-top:24px!important}
.chm-faq{border-top:1px solid var(--line)}.chm-faq details{border-bottom:1px solid var(--line);padding-block:22px}.chm-faq summary{cursor:pointer;list-style:none;font-size:15px;line-height:1.5;font-weight:600;display:flex;gap:20px;align-items:center;justify-content:space-between}.chm-faq summary::-webkit-details-marker{display:none}.chm-faq summary::after{content:'+';font-size:22px;font-weight:400;flex-shrink:0}.chm-faq details[open] summary::after{content:'−'}.chm-faq details p{font-size:14px;color:var(--muted);line-height:1.8;padding-top:16px;max-width:760px}.chm-closing{background:var(--green);border-radius:20px;padding:58px 64px;color:var(--cream);display:flex;align-items:center;justify-content:space-between;gap:45px}.chm-closing h2{font-size:43px;max-width:600px}.chm-closing p{font-size:14px;margin-top:17px;max-width:520px;color:#dbe4d5}.chm-closing .chm-eyebrow{color:#e9b99c}.chm-closing .chm-button{background:var(--cream);border-color:var(--cream);color:var(--green)!important;white-space:nowrap}.chm-closing .chm-button-secondary{background:transparent;color:var(--cream)!important;border-color:#9db0a1}.chm-closing .chm-actions{margin-top:0;flex-shrink:0}
@media(min-width:1600px){.chm-hero-title{font-size:76px}}
@media(max-width:1100px){.chm-wrap{padding-inline:36px}.chm-header::after{left:36px;right:36px}.chm-hero{gap:36px}.chm-hero-title{font-size:59px}.chm-nav{gap:18px}.chm-header-login{margin-left:0}.chm-split{gap:45px}.chm-packages{gap:12px}.chm-package{padding:24px 17px}.chm-closing{padding:45px}.chm-closing h2{font-size:36px}}
@media(max-width:800px){.chm-wrap{padding-inline:24px}.chm-header{min-height:83px;gap:18px}.chm-header::after{left:24px;right:24px}.chm-logo img{width:86px}.chm-logo{min-width:86px}.chm-logo span{font-size:7px}.chm-nav{display:none}.chm-header-login{margin-left:auto;font-size:12px;padding-inline:18px;gap:10px;min-height:42px}.chm-menu{display:block}.chm-menu summary{cursor:pointer;font-size:12px;list-style:none;padding:12px 0;display:flex;gap:8px}.chm-menu summary::-webkit-details-marker{display:none}.chm-menu nav{position:absolute;top:78px;left:24px;right:24px;background:var(--paper);z-index:20;border:1px solid var(--line);border-radius:12px;box-shadow:0 15px 35px #183d3320;display:grid;padding:15px}.chm-menu nav a{padding:10px;font-size:14px;text-decoration:none}.chm-hero{padding-block:44px 55px;gap:42px;grid-template-columns:1fr}.chm-hero-title{font-size:clamp(44px,8vw,66px);max-width:620px}.chm-lead{font-size:16px;margin-top:22px!important}.chm-hero-visual{max-width:560px;width:100%;margin-inline:auto}.chm-hero-photo{aspect-ratio:1.2;border-radius:140px 140px 12px 12px}.chm-balance-card{left:-7px;bottom:20px;padding:17px 21px;min-width:210px}.chm-benefit-strip{gap:20px;grid-template-columns:1fr;padding-block:25px}.chm-benefit-item p{margin-top:2px}.chm-section{padding-block:58px}.chm-steps{gap:25px}.chm-step h3{font-size:24px}.chm-step p{font-size:13px}.chm-split{grid-template-columns:1fr;gap:36px}.chm-section-heading{margin-bottom:30px}.chm-packages{grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.chm-package{padding:24px}.chm-closing{display:block;padding:35px 28px;border-radius:14px}.chm-closing h2{font-size:36px}.chm-closing .chm-actions{margin-top:27px}}
@media(max-width:480px){.chm-hero-title{font-size:46px}.chm-eyebrow{font-size:10px;margin-bottom:17px!important}.chm-actions{gap:12px}.chm-button{font-size:12px;padding:14px 20px;min-height:50px}.chm-hero .chm-actions{align-items:stretch}.chm-hero .chm-button-secondary{padding-inline:15px}.chm-hero-photo{aspect-ratio:1.1}.chm-steps{grid-template-columns:1fr;gap:27px}.chm-step{display:grid;grid-template-columns:28px 1fr;gap:0 12px;padding-top:20px}.chm-step>span:first-child{grid-row:1/3;margin-top:5px;margin-bottom:0}.chm-step h3{font-size:26px;margin-bottom:10px}.chm-step p{grid-column:2;font-size:14px}.chm-packages{gap:12px}.chm-package{padding:21px 15px}.chm-package h3{font-size:25px;margin-bottom:16px}.chm-package .chm-price{font-size:35px}.chm-package .chm-button{font-size:10px;min-height:48px;padding:11px 8px}.chm-package-total{font-size:13px}.chm-package p{font-size:11px}.chm-badge{font-size:9px;padding:5px 8px}.chm-section-heading>p:not(.chm-eyebrow){font-size:14px}.chm-faq summary{font-size:14px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.chm *{transition:none!important}}
